import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 6
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))
    records = [record for record in records if record and any(value != "" for value in record)]

    if not records:
        return {"columns": [], "rows": []}

    number_pattern = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")

    def looks_numeric(value):
        return bool(number_pattern.fullmatch(value.strip()))

    header_index = None
    for index, record in enumerate(records):
        if len(record) >= expected_width and any(not looks_numeric(value) for value in record):
            header_index = index
            break

    if header_index is None:
        header_index = 0

    header = list(records[header_index])
    if header:
        header[0] = header[0].lstrip("\ufeff")
    data_rows = records[header_index + 1:]

    width = max(expected_width, len(header), max((len(row) for row in data_rows), default=0))
    columns = header[:]
    while len(columns) < width:
        columns.append("column_" + str(len(columns) + 1))

    rows = []
    for record in data_rows:
        row = list(record)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
